const reduce=matchMedia('(prefers-reduced-motion: reduce)');if(!reduce.matches)document.body.classList.add('js');const observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e));const motion=new IntersectionObserver(es=>es.forEach(e=>e.target.classList.toggle('offscreen',!e.isIntersecting)));document.querySelectorAll('.hero-product,.ai-demo,.solution-visual').forEach(e=>motion.observe(e));const button=document.querySelector('#motion');let paused=reduce.matches;function update(){document.body.classList.toggle('paused',paused);button.setAttribute('aria-pressed',String(paused));button.textContent=paused?'▶ Retomar animações':'Ⅱ Pausar animações'}button.addEventListener('click',()=>{paused=!paused;update()});reduce.addEventListener('change',e=>{paused=e.matches;update();if(e.matches)document.querySelectorAll('.reveal').forEach(x=>x.classList.add('visible'))});document.addEventListener('visibilitychange',()=>document.body.classList.toggle('hidden',document.hidden));update();